public class StudentResultCardGenerator { static class Student { String name; int[] marks; Student(String n,int[] m){name=n;marks=m;} double average(){return (marks[0]+marks[1]+marks[2])/3.0;} char grade(){double a=average();return a>=75?'B':a>=60?'C':a>=40?'D':'F';} void print(){System.out.printf("%s: Average %.1f, Grade %c%n",name.toUpperCase(),average(),grade());} } public static void main(String[] args){new Student("Asha",new int[]{80,90,70}).print();new Student("Ravi",new int[]{60,55,50}).print();} }
